@pytest.mark.parametrize("padding", [b"", b" \t \t"])
@pytest.mark.parametrize("ending", [b"", b"\r\n"])
def test_fragmented_delimiters_preserve_payload(padding, ending):
    boundary = b"a.+$^()[]?"
    token = b"--" + boundary
    payload = b"\x00\xff\r\n\n\r" + b"".join(
        b"\r\n" + token + suffix
        for suffix in (b"--X", b"--!", b"---", b"----", b" \tX", b"-- \tX")
    ) + b"\r"
    values = [payload, b"", b"\r", b"\n", b"\r\n", b"\x00"]
    body = b"preamble\r\n" + b"".join(
        token + padding + b"\r\n"
        b'Content-Disposition: form-data; name="same"; filename="sample.bin"\r\n'
        b"Content-Type: application/octet-stream\r\n\r\n"
        + value + b"\r\n"
        for value in values
    ) + token + b"--" + padding + ending

    def decode(chunks):
        decoder = MultipartDecoder(boundary)
        result = []
        for chunk in [*chunks, None]:
            decoder.receive_data(chunk)
            while True:
                event = decoder.next_event()
                if isinstance(event, NeedData):
                    break
                if isinstance(event, File):
                    assert event.name == "same"
                    assert event.filename == "sample.bin"
                    assert event.headers["Content-Type"] == "application/octet-stream"
                    result.append(bytearray())
                elif isinstance(event, Data):
                    result[-1].extend(event.data)
                    if not event.more_data:
                        assert result[-1] == values[len(result) - 1]
                elif isinstance(event, Epilogue):
                    assert result == values
                    return
        pytest.fail("Missing epilogue")

    for split in range(len(body) + 1):
        decode([body[:split], body[split:]])
    decode([body[i : i + 1] for i in range(len(body))])


@pytest.mark.parametrize("padding", [b"", b" \t"])
def test_closing_token_needs_line_break_or_eof(padding):
    decoder = MultipartDecoder(b"foo")
    decoder.receive_data(
        b'--foo\r\nContent-Disposition: form-data; name="x"\r\n\r\n'
        b"payload\r\n--foo--" + padding
    )
    assert isinstance(decoder.next_event(), Preamble)
    assert isinstance(decoder.next_event(), Field)
    assert decoder.next_event() == Data(b"payload", more_data=True)
    assert isinstance(decoder.next_event(), NeedData)
    decoder.receive_data(None)
    assert decoder.next_event() == Data(b"", more_data=False)
    assert isinstance(decoder.next_event(), Epilogue)


