@pytest.mark.parametrize("read_size", [1, 7, 65536])
def test_multipart_binary_payload_short_reads(read_size):
    class ShortReadStream(io.BytesIO):
        def read(self, size=-1):
            return super().read(read_size if size < 0 else min(size, read_size))

        def readinto(self, buffer):
            data = self.read(len(buffer))
            buffer[: len(data)] = data
            return len(data)

    payload = b"\x00" * 65535 + b"\r\r\n--foo--X\x00\r"
    body = (
        b'--foo\r\nContent-Disposition: form-data; name="x"\r\n\r\n'
        b"first\r\n--foo \t\r\n"
        b'Content-Disposition: form-data; name="x"\r\n\r\n'
        b"\r\n--foo\r\n"
        b'Content-Disposition: form-data; name="f"; filename="sample.bin"\r\n'
        b"Content-Type: application/octet-stream\r\n\r\n"
        + payload + b"\r\n--foo-- \t"
    )
    parser = FormDataParser(silent=False)
    _, form, files = parser.parse(
        ShortReadStream(body), "multipart/form-data", len(body), {"boundary": "foo"}
    )
    assert form.getlist("x") == ["first", ""]
    assert files["f"].read() == payload
    assert files["f"].filename == "sample.bin"
    assert files["f"].content_type == "application/octet-stream"
    files["f"].close()

    with Request.from_values(
        input_stream=ShortReadStream(body),
        content_length=len(body),
        content_type="multipart/form-data; boundary=foo",
        method="POST",
    ) as request:
        assert request.form.getlist("x") == ["first", ""]
        assert request.files["f"].read() == payload
